package com.bocsoft.sqleditor.execution;
import com.bocsoft.sqleditor.auth.*;import com.bocsoft.sqleditor.common.RequestIds;import com.bocsoft.sqleditor.config.SqlEditorProperties;import com.bocsoft.sqleditor.execution.api.*;import javax.servlet.http.HttpServletRequest;import javax.validation.Valid;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.core.task.AsyncTaskExecutor;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import org.springframework.web.context.request.async.WebAsyncTask;
@RestController @RequestMapping("/api/v1/sql/executions") public class SqlExecutionController {private final SqlExecutionService service;private final AsyncTaskExecutor executor;private final long timeoutMs;public SqlExecutionController(SqlExecutionService service,@Qualifier("sqlExecutionExecutor")AsyncTaskExecutor executor,SqlEditorProperties properties){this.service=service;this.executor=executor;this.timeoutMs=(properties.getExecution().getTimeoutSeconds()+5L)*1000L;}
 @PostMapping public WebAsyncTask<SqlExecutionResponse>execute(@Valid @RequestBody SqlExecutionRequest request,HttpServletRequest servlet){AuthContext auth=CurrentAuth.get();String requestId=String.valueOf(servlet.getAttribute(RequestIds.ATTRIBUTE));WebAsyncTask<SqlExecutionResponse>task=new WebAsyncTask<SqlExecutionResponse>(timeoutMs,executor,()->service.execute(auth,request,requestId));task.onTimeout(()->{service.cancel(auth,request.getExecutionId());return null;});return task;}
 @PostMapping("/{id}:cancel")public ResponseEntity<Void>cancel(@PathVariable String id){service.cancel(CurrentAuth.get(),id);return ResponseEntity.accepted().build();}}
